syntax:
namespace N {
    struct A {
        friend void f(A&);
        operator int();
    };
}

code_example:
namespace N {
    struct A {
        friend void f(A& a);
        operator int() const { return 42; }
    };
    void f(A& a) {
        std::cout << "Friend function called." << std::endl;
        int value = a; // uses operator int()
        std::cout << "Converted value: " << value << std::endl;
    }
}
int main() {
    N::A a;
    N::f(a);
    int val = a; // implicit conversion via operator int()
    std::cout << "Main: value = " << val << std::endl;
    return 0;
}
